import {seed,validate,uid,today,localDateTime,missionDefaults,xpFor,progress,level,complete,purchase,themes,defaultAppearance,resistanceLabels,slipLabels,drainLabels,reminderTimes,alarmPlan,checkSchedule,vitals,coinsFor,defaultCoins} from './engine.js';
import {sprite,hairNames,clothesNames,itemNames} from './character.js';
import {icons,iconSvg} from './icons.js';
import {outfitParts,itemParts,outfitPalette,itemPalette,eyeNames} from './customization.js';
import {radarSvg} from './radar.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const native=!!window.DaemonNative,fmt=v=>new Date(v).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
let loadError=false,state;try{const stored=localStorage.getItem('daemon-deck');state=stored?validate(JSON.parse(stored)):seed();}catch{state=seed();loadError=true;}
let selectedSkill='',newSkillParent='',characterDraft=null;
let page='deck',filter='active',query='',sort='suggested',category='all',draft=null,dirty=false,editingImage='',nativeStatus={},alarmError='';
const nav=[['deck','▦','Deck'],['missions','⚑','Missions'],['skills','◈','Skills'],['rewards','⬡','Exchange'],['journal','▤','Logs'],['settings','⚙','Config']];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function syncAlarms(){try{if(native){const result=JSON.parse(window.DaemonNative.setAlarms(JSON.stringify(alarmPlan(state))));alarmError=result.error||'';if(alarmError)toast(alarmError);}}catch{alarmError='Alarm scheduling failed. Check Config → Alarm access.';toast(alarmError);}}
function persist(){try{validate(state);localStorage.setItem('daemon-deck',JSON.stringify(state));loadError=false;syncAlarms();return true;}catch(e){toast(e.name==='QuotaExceededError'?'Storage full. Export a backup and remove large images.':e.message);return false;}}
function mutate(fn){const previous=structuredClone(state);try{fn();if(!persist()){state=previous;return false;}return true;}catch(e){state=previous;toast(e.message);return false;}}
function applyAppearance(a){const root=document.documentElement;for(const k of ['accent','secondary','bg','panel','text'])root.style.setProperty('--'+k,a[k]);root.style.setProperty('--text-scale',(a.textScale||100)/100);root.style.setProperty('--ui-scale',(a.uiScale||100)/100);root.dataset.subtheme=a.subtheme;root.dataset.scanlines=a.scanlines;document.body.classList.toggle('compact',a.compact);}
function go(next){if(page==='settings'&&dirty){if(!confirm('Save these settings? Cancel to keep editing.'))return;if(!saveAppearance())return;}page=next;selectedSkill='';filter='active';query='';category='all';if(next==='settings')draft=structuredClone(state.settings.appearance);render();scrollTo(0,0);}
function saveAppearance(){if(!draft)return true;if(!mutate(()=>state.settings.appearance=structuredClone(draft)))return false;dirty=false;toast('Appearance saved.');return true;}
function art(x){return x.image?`<img class="item-art" src="${esc(x.image)}" alt="">`:`<span class="item-art">${iconSvg(x.icon)||esc(x.icon||'⌁')}</span>`;}
function xpBar(x){const p=progress(x);return `<div class="bar" role="meter" aria-label="Level XP" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.current}"><i style="width:${p.current/p.total*100}%"></i></div>`;}
function heading(code,title,desc,action=''){return `<div class="section-heading"><div><span class="eyebrow">${code}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function permissionState(){if(!native)return {};try{return JSON.parse(window.DaemonNative.getPermissionState());}catch{return {notifications:false,exact:false,battery:false,error:'Unable to read Android permissions.'};}}
function permissionPanel(gate=false){const s=permissionState();return `<section class="panel permission-panel"><div class="panel-title"><h2>${gate?'ALARM ACCESS REQUIRED':'Alarm access'}</h2><span class="chip">ANDROID</span></div><p>Enable notifications, exact alarms, and unrestricted battery access before entering the deck.</p>${[['notifications','Notifications','Display and sound mission alerts.'],['exact','Alarms & reminders','Schedule exact alarms while the app is closed.'],['battery','Unrestricted battery','Allow scheduling outside normal battery optimization.']].map(([k,name,desc])=>`<div class="permission-row"><span class="status-led ${s[k]?'ok':''}"></span><div><b>${name}</b><small>${desc}</small></div><button class="${s[k]?'text-button':'primary'}" data-permission="${k}">${s[k]?'Settings':'Enable'}</button></div>`).join('')}<p class="fine-print">Android retains final control: Do Not Disturb, disabled notification channels, force-stop, and manufacturer battery rules can silence or delay alarms. No app can bypass these restrictions.</p>${gate?'<button class="secondary" data-action="refresh-permissions">Recheck access ↻</button>':'<button class="secondary" data-action="test-alarm">Send test alert</button>'}${s.error?`<p role="alert">${esc(s.error)}</p>`:''}${alarmError?`<p role="alert">${esc(alarmError)}</p>`:''}</section>`;}
function render(){applyAppearance(page==='settings'&&draft?draft:state.settings.appearance);nativeStatus=permissionState();if(native&&(!nativeStatus.notifications||!nativeStatus.exact||!nativeStatus.battery)){$('#app').innerHTML=`<main class="setup"><div class="setup-brand">DÆMON<span>// DECK</span></div>${permissionPanel(true)}<small class="eyebrow">LOCAL SYSTEM · NO ACCOUNT REQUIRED</small></main>`;bind();return;}
 const p=progress(state.profile.xp);$('#app').innerHTML=`<aside class="sidebar"><a href="#deck" class="brand" data-go="deck"><img src="icon.svg" alt="">DÆMON<span>DECK</span></a><div class="workspace-label">PERSONAL OPERATING SYSTEM</div><nav>${nav.map(([k,icon,title])=>`<button class="nav-item ${page===k?'active':''}" data-go="${k}"><span>${icon}</span>${title}${k==='missions'?`<small>${state.missions.filter(m=>m.status==='active').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="system-state"><i></i> LOCAL STORAGE <span>ONLINE</span></div><button class="profile-mini" data-action="profile"><div class="mini-sprite">${characterView()}</div><div><b>${esc(state.profile.name)}</b><small>LVL ${p.level} / ${esc(state.profile.title)}</small></div><span>↗</span></button><small class="build-id">DÆMON OS / 0.4.0 · OVERHAUL</small></div></aside><main><header class="topbar"><div class="breadcrumb">DÆMON OS <span>/</span> <b>${nav.find(n=>n[0]===page)[2].toUpperCase()}</b></div><div class="top-actions"><span class="connection"><i></i> LOCAL</span><span class="coin">⬡ ${state.profile.coins} <small>CR</small></span><button class="avatar-button" data-action="profile" aria-label="Edit operator">${state.profile.name[0]?esc(state.profile.name[0].toUpperCase()):'Ø'}</button></div></header><div class="main-content">${loadError?'<div class="error-banner">Stored data could not be loaded. <button class="text-button" data-action="export-raw">Download original data before editing</button></div>':''}${({deck,missions,skills,rewards,journal,settings})[page]()}</div><footer><span>DÆMON DECK / 02</span><span>LOCAL FIRST. OPERATOR CONTROLLED.</span><span>EXTENSIVE_OVERHAUL</span></footer></main><nav class="mobile-nav">${nav.filter(n=>n[0]!=='journal').map(([k,icon,title])=>`<button data-go="${k}" class="${page===k?'active':''}">${icon}<small>${title}</small></button>`).join('')}</nav>`;bind();}
function characterView(c=state.profile.character,image=state.profile.avatar){return `<span class="avatar-scale" style="--avatar-scale:${(c.scale||100)/100}">`+( c.mode==='image'&&image?`<img class="operator-image" src="${esc(image)}" alt="Custom operator">`:sprite(c))+'</span>';}
function deck(){const p=progress(state.profile.xp),completed=state.history.filter(h=>h.type==='complete'),active=state.missions.filter(m=>m.status==='active'),overdue=active.filter(m=>Date.parse(m.dueAt)<Date.now()).length;return `<div class="deck-heading"><div><span class="eyebrow">// OPERATOR TERMINAL</span><h1>${esc(state.profile.name)}<span class="cursor">_</span></h1></div><span class="chip">PROFILE / LOCAL</span></div><section class="operator-console"><div class="console-top"><span><i class="status-led ok"></i> OPERATOR_LINK.ACTIVE</span><span>SYS / ${String(p.level).padStart(2,'0')}</span></div><div class="operator-grid"><div class="operator-info"><span class="eyebrow">IDENTITY</span><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.title)}</p><div class="level-display"><span>LVL</span><b>${String(p.level).padStart(2,'0')}</b><small>${state.profile.xp} TOTAL XP</small></div>${xpBar(state.profile.xp)}<small>${p.current} / ${p.total} XP → LVL ${p.level+1}</small><button class="secondary" data-action="profile">Edit operator ↗</button></div><div class="character-screen" ${state.settings.cover?`style="background-image:linear-gradient(#07122177,#07122177),url('${esc(state.settings.cover)}')"`:''}><span class="screen-coordinate">X:024 / Y:032</span><div class="pixel-stage">${characterView()}</div><div class="floor-grid"></div><div class="character-controls"><button class="secondary" data-action="profile">EDIT OPERATOR ↗</button></div></div><div class="operator-telemetry"><span class="eyebrow">TELEMETRY</span>${vitalsPanel()}<div class="telemetry"><span>ACTIVE</span><b>${String(active.length).padStart(2,'0')}</b></div><div class="telemetry"><span>OVERDUE</span><b class="${overdue?'warning':''}">${String(overdue).padStart(2,'0')}</b></div></div></div><div class="console-bottom"><span>CHARACTER_ENGINE / 24 × 32 PX</span><span>LOCAL SAVE <i>●</i></span></div></section><section class="analytics"><div class="panel-title"><h2>Operator analytics</h2><span class="eyebrow">LIVE / ON DEVICE</span></div><div class="stat-grid"><div class="stat"><small>MISSIONS CLEARED</small><b>${completed.length.toString().padStart(2,'0')}</b><span>${completed.filter(h=>new Date(h.at).toDateString()===new Date().toDateString()).length} today</span></div><div class="stat"><small>EXPERIENCE</small><b>${state.profile.xp}</b><span>${completed.reduce((n,h)=>n+(h.xp||0),0)} XP from logged completions</span></div><div class="stat"><small>CREDITS</small><b>${state.profile.coins}</b><span>${state.rewards.reduce((n,r)=>n+r.inventory,0)} items in inventory</span></div><div class="stat activity-stat"><small>ACTIVITY / LAST 7 DAYS</small>${activityChart(completed)}</div></div></section><section class="panel deck-skill-web"><div class="panel-title"><h2>Skill web</h2><span class="chip">MAIN SKILLS / XP</span></div><button class="radar-trigger" data-action="radar" aria-label="Expand skill web to all skills">${radarSvg(state.skills.filter(s=>!s.parentId))}<span class="radar-expand">TAP TO EXPAND / MAIN + SUBSKILLS ↗</span></button><div class="radar-legend">${state.skills.filter(s=>!s.parentId).map(s=>`<span><b>${esc(s.title)}</b><small>${s.xp} XP</small></span>`).join('')}</div></section>`;}
function activityChart(history){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return {date:d,count:history.filter(h=>new Date(h.at).toDateString()===d.toDateString()).length};}),max=Math.max(1,...days.map(d=>d.count));return `<div class="activity-chart" role="img" aria-label="${esc(days.map(d=>`${d.date.toLocaleDateString()}: ${d.count} completions`).join('; '))}">${days.map(d=>`<div title="${d.count} cleared"><b>${d.count}</b><i style="height:${Math.max(2,d.count/max*44)}px"></i><small>${d.date.toLocaleDateString([],{weekday:'narrow'})}</small></div>`).join('')}</div>`;}
function tabs(items){return `<div class="tabs">${items.map(([k,label])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${label}</button>`).join('')}</div>`;}
function score(m){return (Date.parse(m.dueAt)<Date.now()?100:0)+m.resistance*4+m.slipRate*2;}
function getMissions(){return state.missions.filter(m=>(filter==='completed'?m.status==='completed':filter==='failed'?m.status==='failed':m.status==='active'&&(filter!=='today'||localDateTime(m.dueAt).slice(0,10)===today())&&(filter!=='overdue'||Date.parse(m.dueAt)<Date.now()))&&(category==='all'||m.category===category)&&`${m.title} ${m.description} ${m.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title):sort==='xp'?xpFor(b)-xpFor(a):sort==='due'?Date.parse(a.dueAt)-Date.parse(b.dueAt):score(b)-score(a));}
function missionRows(items){return items.length?items.map(m=>`<article class="mission-row ${m.status==='completed'?'done':''}"><button class="complete" data-complete="${m.id}" ${m.status!=='active'?'disabled':''} aria-label="Complete ${esc(m.title)}">${m.status==='completed'?'✓':''}</button><button class="mission-main" data-edit="mission:${m.id}">${art(m)}<div><b>${esc(m.title)}</b><p>${esc(m.description)}</p><div class="metadata"><span class="tag">${esc(m.category)}</span><span class="${Date.parse(m.dueAt)<Date.now()&&m.status==='active'?'warning':''}">◷ ${esc(fmt(m.dueAt))}</span>${m.reminderCount?`<span>◉ ${m.reminderCount} pre-alerts</span>`:''}${m.repeat!=='none'?`<span>↻ ${m.repeat}</span>`:''}${m.subtasks.length?`<span>${m.subtasks.filter(t=>t.done).length}/${m.subtasks.length} steps</span>`:''}${m.parent?'<span>↳ Child</span>':''}</div></div></button><div class="mission-reward"><b>+${xpFor(m)} <small>XP</small></b><span>⬡ ${coinsFor(m)} CR</span></div><button class="more" data-edit="mission:${m.id}" aria-label="Edit ${esc(m.title)}">⋯</button></article>`).join(''):'<div class="empty"><span>∅</span><h3>No missions in this view</h3><p>Change filters or add a mission.</p></div>';}
function missions(){return heading('// MISSION CONTROL','Mission queue','Due dates, pre-alerts, and execution parameters.','<button class="primary" data-action="new-mission">＋ New mission</button>')+`<div class="toolbar"><label class="search">⌕ <input id="search" placeholder="Search missions" value="${esc(query)}" aria-label="Search missions"></label><select id="category" aria-label="Category"><option value="all">All categories</option>${[...new Set(state.missions.map(m=>m.category))].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="sort" aria-label="Sort missions">${[['suggested','Suggested'],['due','Due date'],['xp','Highest XP'],['name','Name']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div>${tabs([['active','Pending'],['today','Today'],['overdue','Overdue'],['completed','Cleared'],['failed','Failed']])}<div class="mission-list">${missionRows(getMissions())}</div>`;}
function skills(){const parent=state.skills.find(s=>s.id===selectedSkill&&!s.parentId);const items=state.skills.filter(s=>parent?s.parentId===parent.id:!s.parentId);return heading('// SKILL MODULES',parent?esc(parent.title):'Skills',parent?'Selected subskills each receive 45% of this main skill’s mission XP.':'Select a main skill to open its subskills.',parent?`<button class="primary" data-add-sub="${parent.id}">＋ Add subskill</button>`:'<button class="primary" data-action="new-skill">＋ New skill</button>')+(parent?`<div class="skill-detail-header"><button class="secondary" data-skill-back>← Main skills</button><button class="text-button" data-edit="skill:${parent.id}">Edit main skill ↗</button><span>${parent.xp} XP / LVL ${level(parent.xp)}</span></div>`:'')+`<div class="card-grid">${items.map(s=>{const p=progress(s.xp);return `<article class="panel skill-card"><button class="skill-open" ${parent?`data-edit="skill:${s.id}"`:`data-skill-open="${s.id}"`}>${art(s)}<span class="card-kicker">${esc(s.category)}</span><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></button><div class="level-line"><b>LVL ${p.level}</b><small>${s.xp} XP</small></div>${xpBar(s.xp)}<p class="muted">${p.current} / ${p.total} XP</p>${parent?'':`<button class="secondary full" data-skill-open="${s.id}">Subskills / ${state.skills.filter(child=>child.parentId===s.id).length} ↗</button>`}<button class="text-button" data-edit="skill:${s.id}">Configure ↗</button></article>`;}).join('')}</div>`+(parent&&!items.length?'<div class="empty"><h3>No subskills</h3><p>Add a subskill, then assign it in a mission.</p></div>':'');}
function vitalsPanel(){const v=vitals(state),peak={green:5,orange:20,red:29}[v.tone];return `<div class="vitals ${v.tone}" id="vitals" role="img" aria-label="Vitals ${v.label}: ${v.count} unfinished overdue missions; oldest ${v.days} days"><span>VITALS / ${v.label}</span><svg viewBox="0 0 180 64" aria-hidden="true"><path class="vitals-grid" d="M0 16h180M0 32h180M0 48h180M30 0v64M60 0v64M90 0v64M120 0v64M150 0v64"/><path class="heartbeat" d="M0 32H20L27 29 34 32H44L50 37 57 ${peak} 64 ${64-peak} 71 32H98L105 29 112 32H124L130 37 137 ${peak} 144 ${64-peak} 151 32H180"/></svg><small>${v.count?`${v.count} overdue / oldest ${v.days}d`:'All deadlines clear'}</small></div>`;}

function rewards(){return heading('// CREDIT EXCHANGE','Exchange','Mission credits. Operator-defined rewards.','<button class="primary" data-action="new-reward">＋ New reward</button>')+`<div class="reward-banner"><span>⬡</span><h2>${state.profile.coins} <small>CR AVAILABLE</small></h2></div><div class="card-grid">${state.rewards.map(r=>`<article class="panel reward-card">${art(r)}<span class="card-kicker">${esc(r.category)}</span><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><p class="muted">${r.quantity<0?'Unlimited stock':`${r.quantity} in stock`} / ${r.purchases} redeemed</p><div class="card-actions"><button class="primary" data-buy="${r.id}" ${state.profile.coins<r.cost||r.quantity===0?'disabled':''}>Redeem / ${r.cost} CR</button><button class="more" data-edit="reward:${r.id}" aria-label="Edit reward">⋯</button></div>${r.inventory?`<div class="inventory">INVENTORY × ${r.inventory}<button class="text-button" data-use="${r.id}">Use one ↗</button></div>`:''}</article>`).join('')}</div>`;}
function journal(){return heading('// EVENT STREAM','Activity log','Local mission and exchange history.')+`<section class="panel">${state.history.length?state.history.map(h=>`<div class="history-row"><span>${h.type==='complete'?'✓':h.type==='fail'?'×':'⬡'}</span><div><b>${esc(h.title)}</b><small>${esc(fmt(h.at))}</small></div><div>${h.xp?`+${h.xp} XP`:''}<small>${h.coins||0} CR</small></div></div>`).join(''):'<div class="empty">NO EVENTS RECORDED</div>'}</section>`;}
function settings(){draft??=structuredClone(state.settings.appearance);return heading('// SYSTEM CONFIG','Configuration','Appearance, alarms, and local data.')+`<div class="settings-grid"><section class="panel appearance-panel"><div class="panel-title"><h2>Appearance</h2><button class="primary" id="save-appearance" data-action="save-appearance" ${!dirty?'disabled':''}>Save${dirty?' *':''}</button></div><p id="appearance-status" role="status">${dirty?'Unsaved preview. Save these settings.':'Configuration saved.'}</p><div class="theme-grid">${Object.entries(themes).map(([id,t])=>`<button data-theme="${id}" class="theme-option ${draft.theme===id?'selected':''}"><span class="swatches"><i style="background:${t.accent}"></i><i style="background:${t.secondary}"></i><i style="background:${t.panel}"></i></span>${t.name}</button>`).join('')}</div><div class="setting"><span>Active theme</span><b id="active-theme">${esc(draft.theme==='custom'?'Custom':themes[draft.theme].name)}</b></div><label class="setting">Subtheme<select id="subtheme">${[['void','Void / high contrast'],['dim','Dim / softer panels'],['light','Daybreak / light']].map(([id,label])=>`<option value="${id}" ${draft.subtheme===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="color-grid">${[['accent','Signal'],['secondary','Secondary'],['bg','Background'],['panel','Panels'],['text','Text']].map(([k,l])=>`<label>${l}<input type="color" data-color="${k}" value="${draft[k]}"></label>`).join('')}</div><label class="setting">CRT scanlines<input id="scanlines" type="checkbox" ${draft.scanlines?'checked':''}></label><label class="setting">Compact rows<input id="compact" type="checkbox" ${draft.compact?'checked':''}></label><label class="field">Text size <output id="textScale-value">${draft.textScale}%</output><input id="textScale" type="range" min="85" max="140" step="5" value="${draft.textScale}"></label><label class="field">Interface size ratio <output id="uiScale-value">${draft.uiScale}%</output><input id="uiScale" type="range" min="85" max="120" step="5" value="${draft.uiScale}"></label><button class="text-button" data-action="discard-appearance">Discard preview</button></section><div><section class="panel"><h2>Operator settings</h2><button class="secondary full" data-action="profile">Edit pixel operator / upload GIF ↗</button><label class="file-button full">Upload character-screen background<input id="cover" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>${state.settings.cover?'<button class="text-button" data-action="clear-cover">Remove background</button>':''}</section><section class="panel data-panel"><h2>Local data</h2><p>Web and Android store data independently. JSON backups transfer profiles, missions, images, and history. V1 backups are migrated automatically.</p><button class="secondary full" data-action="export">↓ Export backup</button><label class="file-button full">↑ Import backup<input id="import" type="file" accept=".json,application/json"></label>${native?'':`<a class="secondary full" href="downloads/daemon-deck-debug.apk" download>↓ Android APK / Overhaul</a><a class="text-button" href="downloads/daemon-deck-source.zip" download>Project source ↗</a>`}</section></div></div><div class="alarm-settings">${native?permissionPanel():`<section class="panel"><h2>Web notifications</h2><p>Browser alerts work while this app is open. Use the Android APK for scheduled alarms with the app closed.</p><button class="secondary" data-action="web-notifications">Enable browser notifications</button><p class="muted" id="web-permission">${'Notification'in window?Notification.permission:'Unavailable in this browser'}</p></section>`}</div><button class="text-button" data-go="journal">Open activity log ↗</button>`;}
function bind(){
 $$('[data-skill-open]').forEach(b=>b.onclick=()=>{selectedSkill=b.dataset.skillOpen;render();scrollTo(0,0);});
 $$('[data-skill-back]').forEach(b=>b.onclick=()=>{selectedSkill='';render();});
 $$('[data-add-sub]').forEach(b=>b.onclick=()=>{newSkillParent=b.dataset.addSub;openEditor('skill');});
 for(const id of ['textScale','uiScale'])if($('#'+id))$('#'+id).oninput=e=>{draft[id]=+e.target.value;$('#'+id+'-value').value=e.target.value+'%';markAppearance();};

 $$('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.go);});
 $$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 $$('[data-edit]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.edit.split(':');openEditor(type,id);});
 $$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 $$('[data-permission]').forEach(b=>b.onclick=()=>window.DaemonNative.requestPermission(b.dataset.permission));
 $$('[data-complete]').forEach(b=>b.onclick=()=>{const id=b.dataset.complete;try{const copy=structuredClone(state);const xp=complete(copy,id);if(xp===null)return;if(mutate(()=>state=copy)){render();toast(`MISSION CLEARED / +${xp} XP`);}}catch(e){toast(e.message);openEditor('mission',id);}});
 $$('[data-buy]').forEach(b=>b.onclick=()=>{if(mutate(()=>purchase(state,b.dataset.buy))){render();toast('REDEEMED / added to inventory');}});
 $$('[data-use]').forEach(b=>b.onclick=()=>{mutate(()=>{const r=state.rewards.find(r=>r.id===b.dataset.use);if(r.inventory>0)r.inventory--;});render();});
 if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 if($('#category'))$('#category').onchange=e=>{category=e.target.value;render();};
 if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render();};
 $$('[data-theme]').forEach(b=>b.onclick=()=>{draft={...draft,...themes[b.dataset.theme],theme:b.dataset.theme};markAppearance(false);render();});
 $$('[data-color]').forEach(c=>c.oninput=()=>{draft[c.dataset.color]=c.value;markAppearance();});
 if($('#subtheme'))$('#subtheme').onchange=e=>{draft.subtheme=e.target.value;markAppearance();};
 for(const id of ['scanlines','compact'])if($('#'+id))$('#'+id).onchange=e=>{draft[id]=e.target.checked;markAppearance();};
 if($('#cover'))$('#cover').onchange=async e=>{try{const image=await readImage(e.target.files[0]);mutate(()=>state.settings.cover=image);render();}catch(e){toast(e.message);}};
 if($('#import'))$('#import').onchange=importBackup;
}
function markAppearance(custom=true){if(custom)draft.theme='custom';dirty=JSON.stringify(draft)!==JSON.stringify(state.settings.appearance);applyAppearance(draft);if($('#save-appearance')){$('#save-appearance').disabled=!dirty;$('#save-appearance').textContent=dirty?'Save *':'Save';$('#appearance-status').textContent=dirty?'Unsaved preview. Save these settings.':'Configuration saved.';$('#active-theme').textContent=draft.theme==='custom'?'Custom':themes[draft.theme].name;$$('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===draft.theme));}}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function rating(name,label,value,labels,max){return `<label class="field rating">${label}<output id="${name}-value">${labels?esc(labels[value-1]):value}</output><input type="range" name="${name}" min="1" max="${max}" step="1" value="${value}" list="${name}-ticks"><datalist id="${name}-ticks">${Array.from({length:max},(_,i)=>`<option value="${i+1}"></option>`).join('')}</datalist><span class="notch-labels">${Array.from({length:max},(_,i)=>`<span>${i+1}</span>`).join('')}</span></label>`;}
function descendant(child,parent){const seen=new Set();while(child&&!seen.has(child)){if(child===parent)return true;seen.add(child);child=state.missions.find(m=>m.id===child)?.parent;}return false;}
function openEditor(type,id){const collection={mission:'missions',skill:'skills',reward:'rewards'}[type],old=state[collection]?.find(i=>i.id===id),x=old||{...missionDefaults(),cost:50,quantity:-1,increase:0};editingImage=type==='profile'?state.profile.avatar:x.image||'';if(type==='profile')characterDraft=structuredClone(state.profile.character);$('#editor').classList.remove('radar-dialog');
 $('#editor').innerHTML=`<form id="item-form"><div class="modal-heading"><div><span class="eyebrow">// CONFIGURATION</span><h2>${type==='profile'?'Operator editor':`${old?'Edit':'New'} ${type}`}</h2></div><button class="close" type="button" data-close aria-label="Close">×</button></div>${type==='profile'?profileFields():`${field('Name','title',x.title,'text','required maxlength="160"')}<label class="field">Description<textarea name="description" rows="2" maxlength="3000">${esc(x.description)}</textarea></label><div class="form-grid">${field('Category','category',x.category,'text','maxlength="60"')}${field('Icon / emoji','icon',x.icon,'text','maxlength="12"')}</div>${iconPicker(x.icon)}${uploadField('Upload icon / image',x.image)}${type==='mission'?missionFields(x,id):type==='reward'?`<div class="form-grid">${field('Cost / CR','cost',x.cost,'number','min="0" max="1000000" required')}${field('Stock (−1 = unlimited)','quantity',x.quantity,'number','min="-1" max="1000000" required')}${field('Cost increase per redemption','increase',x.increase,'number','min="0" max="1000000" required')}</div>`:''}${type!=='reward'?`<label class="field">Private notes<textarea name="notes" rows="3" maxlength="20000">${esc(x.notes)}</textarea></label>`:''}` }<div id="editor-error" class="form-error" role="alert"></div><div class="modal-actions">${old?`<button type="button" class="danger" data-delete>Delete</button>${type==='mission'?`${old.status!=='completed'?`<button type="button" class="secondary" data-status>${old.status==='active'?'Mark failed':'Reopen'}</button>`:''}<button type="button" class="secondary" data-duplicate>Duplicate</button>`:''}`:''}<span></span><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save ${type==='profile'?'operator':type}</button></div></form>`;
 const modal=$('#editor');modal.querySelectorAll('[data-pick-icon]').forEach(b=>b.onclick=()=>{modal.querySelector('[name=icon]').value=b.dataset.pickIcon;modal.querySelectorAll('[data-pick-icon]').forEach(btn=>{btn.classList.toggle('selected',btn===b);btn.setAttribute('aria-pressed',String(btn===b));});});if(!modal.open)modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());
 const upload=modal.querySelector('[name=image]');upload.onchange=async e=>{try{editingImage=await readImage(e.target.files[0],type==='profile');const img=modal.querySelector('.image-preview');img.src=editingImage;img.hidden=false;if(type==='profile')updateCharacterPreview();}catch(e){toast(e.message);}};
 if(type==='profile')bindCharacter();
 if(type==='mission'){
  const updateXP=()=>{const f=Object.fromEntries(new FormData($('#item-form')));for(const [name,labels] of [['friction',null],['resistance',resistanceLabels],['slipRate',slipLabels],['drain',drainLabels]])$('#'+name+'-value').value=labels?labels[+f[name]-1]:f[name];const enabled=$('[name=xpEnabled]').checked;$('#rating-fields').classList.toggle('disabled',!enabled);const params={...f,xpEnabled:enabled,friction:+f.friction,resistance:+f.resistance,slipRate:+f.slipRate,drain:+f.drain};$('#xp-preview').textContent=`${xpFor(params)} XP`;if($('[name=coinMode]').value==='auto')$('[name=coins]').value=defaultCoins(params);$('#credit-mode').textContent=$('[name=coinMode]').value==='auto'?'XP DEFAULT / 1 CR PER 5 XP':'MANUAL OVERRIDE';};
  modal.querySelectorAll('.rating input,[name=xpEnabled]').forEach(input=>input.oninput=updateXP);$('[name=coins]').oninput=()=>{$('[name=coinMode]').value='manual';updateXP();};$('[data-reset-coins]').onclick=()=>{$('[name=coinMode]').value='auto';updateXP();};
  const updateReminders=(keep=false)=>{const f=Object.fromEntries(new FormData($('#item-form')));let created=x.createdAt,due=new Date(f.dueAt);if(!Number.isFinite(+due))return;let count=+f.reminderCount,mode=f.reminderMode,at=reminderTimes({...x,dueAt:due.toISOString(),reminderCount:count,reminderMode:'even'});if(keep&&mode==='manual'){const current=$$('[name=reminderAt]').map(input=>input.value);at=at.map((v,i)=>current[i]?new Date(current[i]).toISOString():v);}$('#reminder-timeline').innerHTML=at.map((v,i)=>`<label class="reminder-slot"><span>0${i+1}</span><input type="datetime-local" name="reminderAt" value="${localDateTime(v)}" ${mode==='even'?'readonly':'required'} aria-label="Pre-reminder ${i+1}">${Date.parse(v)<Date.now()?'<small>ELAPSED</small>':''}</label>`).join('')+`<div class="due-slot"><b>◉ DUE</b><span>${esc(fmt(due))}</span></div>`;};
  $('[name=dueAt]').onchange=()=>updateReminders(false);$('[name=reminderCount]').onchange=()=>updateReminders(true);$('[name=reminderMode]').onchange=()=>updateReminders(false);updateXP();
 }
 if(old)modal.querySelector('[data-delete]').onclick=()=>{if(!confirm(`Delete “${old.title}”?`))return;if(mutate(()=>{state[collection]=state[collection].filter(i=>i.id!==id);if(type==='skill'){const removed=new Set([id,...state.skills.filter(s=>s.parentId===id).map(s=>s.id)]);state.skills=state.skills.filter(s=>!removed.has(s.id));state.missions.forEach(m=>m.skills=m.skills.filter(s=>!removed.has(s)));if(selectedSkill===id)selectedSkill='';}if(type==='mission')state.missions.forEach(m=>{if(m.parent===id)m.parent='';});})){modal.close();render();}};
 if(modal.querySelector('[data-status]'))modal.querySelector('[data-status]').onclick=()=>{if(mutate(()=>{old.status=old.status==='active'?'failed':'active';if(old.status==='failed')state.history.unshift({id:uid(),type:'fail',title:old.title,at:new Date().toISOString()});})){modal.close();render();}};
 if(modal.querySelector('[data-duplicate]'))modal.querySelector('[data-duplicate]').onclick=()=>{if(mutate(()=>{const base=missionDefaults();state.missions.push({...structuredClone(old),id:uid(),title:old.title+' (copy)',status:'active',parent:'',createdAt:base.createdAt,dueAt:base.dueAt,reminderMode:'even',reminderTimes:[],subtasks:old.subtasks.map(t=>({...t,done:false}))});})){modal.close();render();}};
 $('#item-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f);try{
  if(type==='profile'){const c=characterFromForm();if(c.mode==='image'&&!editingImage&&!v.removeImage)throw Error('Upload an image or GIF, or select Pixel operator.');if(mutate(()=>{state.profile.name=v.name.trim()||'Operator';state.profile.title=v.title;state.profile.avatar=v.removeImage?'':editingImage;state.profile.character={...c,mode:v.removeImage?'pixel':c.mode};})){modal.close();render();toast('OPERATOR SAVED');}return;}
  if(!v.title.trim())throw Error('Name is required.');let item={...old,id:id||x.id,title:v.title.trim(),description:v.description,category:v.category,icon:v.icon||'⌁',image:v.removeImage?'':editingImage};
  if(type==='mission'){Object.assign(item,{duration:+v.duration,coins:+v.coins,coinMode:v.coinMode,friction:+v.friction,resistance:+v.resistance,slipRate:+v.slipRate,drain:+v.drain,xpEnabled:f.has('xpEnabled'),repeat:v.repeat,createdAt:x.createdAt,dueAt:new Date(v.dueAt).toISOString(),reminderCount:+v.reminderCount,reminderMode:v.reminderMode,reminderTimes:v.reminderMode==='manual'?f.getAll('reminderAt').map(d=>new Date(d).toISOString()):[],skills:f.getAll('skills'),parent:v.parent,notes:v.notes,location:v.location,status:old?.status||'active',subtasks:v.steps.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>{const i=x.subtasks.findIndex(s=>s.title===t);return {title:t,done:i>=0&&f.getAll('stepdone').includes(String(i))};})});checkSchedule(item);if((!old||old.dueAt!==item.dueAt)&&Date.parse(item.dueAt)<=Date.now())throw Error('Choose a future due date.');}
  if(type==='skill')Object.assign(item,{xp:old?.xp||0,notes:v.notes,parentId:old?old.parentId:(newSkillParent||'')});if(type==='reward')Object.assign(item,{cost:+v.cost,quantity:+v.quantity,increase:+v.increase,purchases:old?.purchases||0,inventory:old?.inventory||0});
  if(mutate(()=>{if(old)state[collection]=state[collection].map(o=>o.id===id?item:o);else state[collection].push(item);})){modal.close();render();toast('SAVED');}
 }catch(e){$('#editor-error').textContent=e.message;$('#editor-error').scrollIntoView({block:'nearest'});}};
}
function uploadField(label,image){return `<label class="file-button full">↑ ${label}<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><img class="image-preview" ${image?`src="${esc(image)}"`:'hidden'} alt="Image preview"><label class="check-label"><input name="removeImage" type="checkbox"> Remove uploaded image</label>`;}
function missionFields(x,id){return `<section class="editor-section"><h3>Schedule / alarms</h3><p class="muted">Created ${esc(fmt(x.createdAt))}. Due alert always scheduled. Pre-reminders divide the creation → due interval into equal segments.</p><div class="form-grid">${field('Due date & time','dueAt',localDateTime(x.dueAt),'datetime-local','required')}${field('Estimated minutes','duration',x.duration,'number','required min="1" max="100000"')}${select('Pre-reminders','reminderCount',Array.from({length:6},(_,i)=>[i,String(i)]),x.reminderCount)}${select('Reminder timing','reminderMode',[['even','Evenly spaced'],['manual','Custom times']],x.reminderMode)}</div><div id="reminder-timeline">${reminderTimes(x).map((v,i)=>`<label class="reminder-slot"><span>0${i+1}</span><input type="datetime-local" name="reminderAt" value="${localDateTime(v)}" ${x.reminderMode==='even'?'readonly':'required'} aria-label="Pre-reminder ${i+1}">${Date.parse(v)<Date.now()?'<small>ELAPSED</small>':''}</label>`).join('')}<div class="due-slot"><b>◉ DUE</b><span>${esc(fmt(x.dueAt))}</span></div></div><p class="fine-print">${native?'Alarms are saved to Android, including when the app is closed.':'Web alerts require an open tab. Install the Android APK for background alarms.'} Elapsed reminders are never replayed.</p></section><section class="editor-section"><div class="panel-title"><h3>XP parameters</h3><label class="switch-label"><input type="checkbox" name="xpEnabled" ${x.xpEnabled?'checked':''}> Earn XP</label></div><div id="rating-fields" class="range-fields">${rating('friction','Friction',x.friction,null,5)}${rating('resistance','Resistance',x.resistance,resistanceLabels,5)}${rating('slipRate','Slip Rate',x.slipRate,slipLabels,4)}${rating('drain','Drain',x.drain,drainLabels,4)}</div><div class="xp-preview"><span>MISSION PAYOUT</span><b id="xp-preview">${xpFor(x)} XP</b></div><p class="fine-print">Drain has the largest XP effect (+0 / 24 / 56 / 96). Friction and Resistance add up to 48 each; Slip Rate adds up to 48.</p></section><div class="form-grid"><div class="currency-editor">${field('Credits earned','coins',coinsFor(x),'number','min="0" max="1000000" step="1" required')}<input type="hidden" name="coinMode" value="${x.coinMode}"><small id="credit-mode">${x.coinMode==='auto'?'XP DEFAULT / 1 CR PER 5 XP':'MANUAL OVERRIDE'}</small><button type="button" class="secondary full" data-reset-coins>Reset to XP default</button></div>${select('Repeat','repeat',['none','daily','weekly','monthly'].map(v=>[v,v]),x.repeat)}</div>${select('Parent mission','parent',[['','Standalone'],...state.missions.filter(m=>m.id!==id&&m.status==='active'&&!descendant(m.id,id)).map(m=>[m.id,m.title])],x.parent||'')}<fieldset><legend>Linked skills</legend>${state.skills.flatMap(parent=>parent.parentId?[]:[parent,...state.skills.filter(c=>c.parentId===parent.id)]).map(s=>`<label class="skill-check"><input type="checkbox" name="skills" value="${s.id}" ${x.skills.includes(s.id)?'checked':''}><span class="inline-icon">${iconSvg(s.icon)||esc(s.icon)}</span> ${s.parentId?'↳ ':''}${esc(s.title)}${s.parentId?' / 45%':''}</label>`).join('')}</fieldset><label class="field">Subtasks <small>One per line. Existing steps can be checked below.</small><textarea name="steps" rows="3">${esc(x.subtasks.map(t=>t.title).join('\n'))}</textarea></label>${x.subtasks.map((t,i)=>`<label class="check-label"><input type="checkbox" name="stepdone" value="${i}" ${t.done?'checked':''}>${esc(t.title)}</label>`).join('')}${field('Location','location',x.location||'','text','maxlength="300"')}`;}
function colorControl(name,label,value){return `<label>${esc(label)}<input name="${name}" type="color" value="${value}"></label>`;}
function paletteFields(c){const outfit=outfitPalette(c),item=itemPalette(c);return `<section class="editor-section"><h3>Outfit parts / ${esc(clothesNames[c.clothes])}</h3><div class="color-grid part-colors">${outfitParts[c.clothes].map(p=>colorControl(`cloth:${c.clothes}:${p.key}`,p.label,outfit[p.key])).join('')}</div></section><section class="editor-section"><h3>Equipment parts / ${esc(itemNames[c.accessory])}</h3>${itemParts[c.accessory].length?`<div class="color-grid part-colors">${itemParts[c.accessory].map(p=>colorControl(`gear:${c.accessory}:${p.key}`,p.label,item[p.key])).join('')}</div>`:'<p class="muted">Select equipment to edit its colors.</p>'}</section>`;}
function profileFields(){const c=characterDraft;return `<div id="character-preview" class="editor-character">${characterView(c)}</div>${field('Handle','name',state.profile.name,'text','required maxlength="60"')}${field('Designation','title',state.profile.title,'text','maxlength="100"')}${select('Display mode','characterMode',[['pixel','Pixel operator'],['image','Custom image / animated GIF']],c.mode)}<section class="editor-section"><h3>Body & hair</h3>${select('Hairstyle','hair',hairNames.map((n,i)=>[i,n]),c.hair)}<div class="color-grid">${colorControl('skin','Skin',c.skin)}${colorControl('hairColor','Hair',c.hairColor)}</div></section><section class="editor-section eye-category"><h3>Eyes</h3>${select('Eye shape','eyeStyle',eyeNames.map((n,i)=>[i,n]),c.eyeStyle)}<div class="color-grid">${colorControl('eyes','Iris',c.eyes)}${colorControl('eyeWhite','White / highlight',c.eyeWhite)}${colorControl('pupilColor','Pupil',c.pupilColor)}</div></section><div class="form-grid">${select('Clothing','clothes',clothesNames.map((n,i)=>[i,n]),c.clothes)}${select('Item','accessory',itemNames.map((n,i)=>[i,n]),c.accessory)}</div><div id="palette-fields">${paletteFields(c)}</div><label class="field">Character size ratio <output id="character-scale-value">${c.scale}%</output><input type="range" name="scale" min="60" max="160" step="5" value="${c.scale}"></label>${uploadField('Upload operator image / GIF',state.profile.avatar)}<p class="fine-print">24 × 32 pixel operator. Each clothing style and item remembers its own palette. Animated GIF uploads retain animation (1.5 MB maximum).</p>`;}
function characterFromForm(){const f=Object.fromEntries(new FormData($('#item-form'))),c=structuredClone(characterDraft);Object.assign(c,{hair:+f.hair,accessory:+f.accessory,clothes:+f.clothes,scale:+f.scale,skin:f.skin,hairColor:f.hairColor,eyes:f.eyes,eyeStyle:+f.eyeStyle,eyeWhite:f.eyeWhite,pupilColor:f.pupilColor,mode:f.characterMode});for(const [name,value] of Object.entries(f)){const match=/^(cloth|gear):(\d+):([a-z]+)$/.exec(name);if(!match)continue;const map=match[1]==='cloth'?c.outfitColors:c.itemColors;map[match[2]]??={};map[match[2]][match[3]]=value;}return c;}
function updateCharacterPreview(){characterDraft=characterFromForm();$('#character-preview').innerHTML=characterView(characterDraft,editingImage);$('#character-scale-value').value=characterDraft.scale+'%';}
function bindCharacter(){$$('#item-form select,#item-form input[type=color],#item-form input[type=range]').forEach(input=>input.oninput=()=>{updateCharacterPreview();if(['clothes','accessory'].includes(input.name)){$('#palette-fields').innerHTML=paletteFields(characterDraft);bindCharacter();}});}
function openSkillRadar(){const modal=$('#editor');modal.classList.add('radar-dialog');const main=state.skills.filter(s=>!s.parentId),all=main.flatMap(p=>[p,...state.skills.filter(s=>s.parentId===p.id)]);modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// OPERATOR STATS</span><h2>Full skill web</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div><p class="muted">All main skills and subskills. Every point uses the same XP scale.</p><div class="radar-full-chart">${radarSvg(all,true)}</div><div class="radar-full-legend">${all.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s.parentId?'↳ ':''}${esc(s.title)}${s.parentId?`<small>${esc(main.find(p=>p.id===s.parentId)?.title||'')}</small>`:''}</b><span>${s.xp} XP</span></div>`).join('')}</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}

async function readImage(file,preserveGif=false){if(!file)throw Error('Select an image.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use PNG, JPG, WebP, or GIF.');if(file.size>10*1024*1024)throw Error('Image limit: 10 MB.');if(preserveGif&&file.type==='image/gif'){if(file.size>1500000)throw Error('Animated GIF limit: 1.5 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read GIF.'));r.readAsDataURL(file);});}return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(Error('Could not read image.'));r.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Invalid image.'));img.onload=()=>{const c=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/webp',.8));};img.src=r.result;};r.readAsDataURL(file);});}
function download(content,name){if(native){window.DaemonNative.exportBackup(content,name);return;}const url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importBackup(e){try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Backup limit: 25 MB.');const incoming=validate(JSON.parse(await file.text()));if(dirty&&!confirm('Discard unsaved appearance settings before import?'))return;if(!confirm('Replace local data with this backup? Export your current data first to keep it.'))return;if(mutate(()=>state=incoming)){dirty=false;draft=structuredClone(state.settings.appearance);render();toast('BACKUP RESTORED');}}catch(e){toast(e.message);}}
async function action(a){if(a.startsWith('new-')){newSkillParent='';return openEditor(a.slice(4));}if(a==='profile')return openEditor('profile');if(a==='radar')return openSkillRadar();if(a==='refresh-permissions'){render();syncAlarms();}if(a==='test-alarm')window.DaemonNative.testAlarm();if(a==='save-appearance'){saveAppearance();render();}if(a==='discard-appearance'){draft=structuredClone(state.settings.appearance);dirty=false;render();}if(a==='clear-cover'){mutate(()=>state.settings.cover='');render();}if(a==='export')download(JSON.stringify(state,null,2),`daemon-deck-${today()}.json`);if(a==='export-raw')download(localStorage.getItem('daemon-deck')||'{}','daemon-deck-original.json');if(a==='web-notifications'){if(!('Notification'in window)){toast('Notifications unavailable in this browser.');return;}const result=await Notification.requestPermission();$('#web-permission').textContent=result;if(result==='denied')toast('Notifications blocked. Change this site’s browser permissions to enable.');}}
window.daemonRefreshPermissions=()=>{render();syncAlarms();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='Save these settings';}});
// Browser notifications are session-only. Persist delivered IDs to avoid duplicates on reload.
let lastWebCheck=Date.now();setInterval(()=>{if(native)return;const now=Date.now();const events=alarmPlan(state,lastWebCheck-1).filter(a=>a.at<=now);if('Notification'in window&&Notification.permission==='granted'){let fired;try{fired=JSON.parse(localStorage.getItem('daemon-web-fired')||'[]');}catch{fired=[];}for(const event of events){const key=event.id+':'+event.at;if(fired.includes(key))continue;try{new Notification(event.title,{body:event.body,icon:'icon.svg',tag:event.id});fired.push(key);}catch{}}try{localStorage.setItem('daemon-web-fired',JSON.stringify(fired.slice(-1000)));}catch{}}lastWebCheck=now;},15000);
setInterval(()=>{if($('#vitals'))$('#vitals').outerHTML=vitalsPanel();},60000);
render();syncAlarms();if('serviceWorker'in navigator&&!native)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function iconPicker(value){return `<details class="icon-library"><summary>Choose icon / 50 symbols</summary><div class="icon-picker">${icons.map(i=>`<button type="button" data-pick-icon="${i.id}" class="${value===i.id?'selected':''}" aria-label="${i.label} icon" aria-pressed="${value===i.id}">${iconSvg(i.id)}<small>${i.label}</small></button>`).join('')}</div></details>`;}
